def slugify(title):
    return title.lower().replace("'", "").replace("&", "and").replace("/", "-").replace("  ", " ").replace(" ", "-").strip("-")

def generate_guides():
    guides = []
    guide_id = 1
    base_date = datetime(2024, 6, 1)

    for cat_name, templates in GUIDE_TEMPLATES.items():
        cat_authors = AUTHOR_BY_CAT.get(cat_name, [AUTHORS[0]["name"]])
        for t in templates:
            created = base_date + timedelta(days=random.randint(0, 400))
            updated = created + timedelta(days=random.randint(5, 60))
            author = random.choice(cat_authors) if random.random() < 0.7 else t.get("author", random.choice(cat_authors))

            views = random.randint(800, 65000)
            rating = round(random.uniform(3.2, 5.0), 1)
            rating = min(rating, 5.0)
            num_ratings = random.randint(15, 900)
            video_dur = t["dur"] * random.randint(40, 80)  # video is longer than guide time in seconds

            guide = {
                "id": guide_id,
                "title": t["title"],
                "slug": slugify(t["title"]),
                "category": cat_name,
                "subcategory": t["sub"],
                "author": author,
                "difficulty": t["diff"],
                "duration_minutes": t["dur"],
                "views": views,
                "rating": rating,
                "num_ratings": num_ratings,
                "description": t["desc"],
                "steps": t["steps"],
                "tags": t["tags"],
                "created": created.strftime("%Y-%m-%d"),
                "updated": updated.strftime("%Y-%m-%d"),
                "video_url": f"/videos/{slugify(t['title'])}.mp4",
                "video_duration_sec": video_dur,
                "thumbnail": f"/thumbs/{slugify(t['title'])}.jpg",
            }
            guides.append(guide)
            guide_id += 1

    return guides


def generate_categories(guides):
    cat_counts = {}
    for g in guides:
        cat_counts[g["category"]] = cat_counts.get(g["category"], 0) + 1

    categories = []
    for c in CATEGORIES:
        c_copy = dict(c)
        c_copy["guide_count"] = cat_counts.get(c["name"], 0)
        categories.append(c_copy)
    return categories


