def generate_comments(guides, users):
    comments = []
    comment_id = 1
    base_date = datetime(2025, 1, 1)
    user_ids = [u["id"] for u in users]

    substitutions = {
        "sub": ["almond flour", "oat milk", "vegan butter", "gluten-free flour", "coconut sugar"],
        "result": ["bread", "painting", "shelf", "code", "croissant"],
        "extra": ["rosemary", "chili flakes", "smoked paprika", "vanilla extract", "lime zest"],
        "fix": ["restarting the service", "updating the firmware", "clearing the cache", "reinstalling the package", "checking permissions"],
        "zone": ["5b", "6a", "7b", "8a", "9b"],
        "amount": ["150", "200", "300", "450", "80"],
        "time": ["25", "30", "45", "60", "90"],
        "subject": ["sunset", "portrait", "macro flower", "Milky Way", "street scene"],
    }

    for guide in guides:
        num_comments = random.randint(1, 6)
        cat = guide["category"]
        templates = COMMENT_TEMPLATES.get(cat, COMMENT_TEMPLATES["Technology"])

        for _ in range(num_comments):
            user_id = random.choice(user_ids)
            template = random.choice(templates)
            text = template
            # Fill in placeholders
            for key, values in substitutions.items():
                placeholder = "{" + key + "}"
                if placeholder in text:
                    text = text.replace(placeholder, random.choice(values))
            if "{step}" in text:
                step_num = random.randint(2, min(len(guide["steps"]), 5))
                text = text.replace("{step}", str(step_num))

            created = base_date + timedelta(days=random.randint(0, 500))

            comment = {
                "id": comment_id,
                "guide_id": guide["id"],
                "user_id": user_id,
                "text": text,
                "created": created.strftime("%Y-%m-%d"),
                "likes": random.randint(0, 30),
                "parent_id": None,
            }
            comments.append(comment)
            comment_id += 1

        # Add some threaded replies
        if num_comments >= 2 and random.random() < 0.5:
            parent = random.choice([c for c in comments if c["guide_id"] == guide["id"]])
            reply_user = random.choice([uid for uid in user_ids if uid != parent["user_id"]])
            reply_templates = [
                "Thanks for the tip! I'll try that.",
                "Good question, I had the same one.",
                "Agreed, that step is the most important part.",
                "I had a similar experience. It gets easier with practice.",
                "Great point! Safety always comes first.",
                "I found that using a different approach also works well.",
                "This is exactly the advice I needed. Thank you!",
            ]
            reply = {
                "id": comment_id,
                "guide_id": guide["id"],
                "user_id": reply_user,
                "text": random.choice(reply_templates),
                "created": (datetime.strptime(parent["created"], "%Y-%m-%d") + timedelta(days=random.randint(1, 5))).strftime("%Y-%m-%d"),
                "likes": random.randint(0, 10),
                "parent_id": parent["id"],
            }
            comments.append(reply)
            comment_id += 1

    return comments


def update_user_comment_counts(users, comments):
    counts = {}
    for c in comments:
        counts[c["user_id"]] = counts.get(c["user_id"], 0) + 1
    for u in users:
        u["comments_count"] = counts.get(u["id"], 0)


def main():
    print("Generating how-to guide data...")

    guides = generate_guides()
    print(f"  Generated {len(guides)} guides across {len(CATEGORIES)} categories")

    categories = generate_categories(guides)
    print(f"  Generated {len(categories)} categories with guide counts")

    users = generate_users(guides)
    print(f"  Generated {len(users)} users")

    comments = generate_comments(guides, users)
    print(f"  Generated {len(comments)} comments")

    update_user_comment_counts(users, comments)

    # Print stats
    by_cat = {}
    by_diff = {}
    by_author = {}
    for g in guides:
        by_cat[g["category"]] = by_cat.get(g["category"], 0) + 1
        by_diff[g["difficulty"]] = by_diff.get(g["difficulty"], 0) + 1
        by_author[g["author"]] = by_author.get(g["author"], 0) + 1

    print("\n  Category distribution:")
    for cat, count in sorted(by_cat.items()):
        print(f"    {cat}: {count}")
    print(f"\n  Difficulty distribution:")
    for diff, count in sorted(by_diff.items()):
        print(f"    {diff}: {count}")
    print(f"\n  Authors: {len(by_author)} unique authors")

    # Write output
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)

    with open(OUTPUT_DIR / "guides.json", "w") as f:
        json.dump(guides, f, indent=4)
    with open(OUTPUT_DIR / "categories.json", "w") as f:
        json.dump(categories, f, indent=4)
    with open(OUTPUT_DIR / "users.json", "w") as f:
        json.dump(users, f, indent=4)
    with open(OUTPUT_DIR / "comments.json", "w") as f:
        json.dump(comments, f, indent=4)

    print(f"\n  Data written to {OUTPUT_DIR}")

    # Also write to .pristine
    pristine_dir = OUTPUT_DIR / ".pristine"
    pristine_dir.mkdir(parents=True, exist_ok=True)
    for fname in ["guides.json", "categories.json", "users.json", "comments.json"]:
        with open(pristine_dir / fname, "w") as f:
            json.dump(json.loads((OUTPUT_DIR / fname).read_text()), f, indent=4)
    print(f"  Pristine snapshot written to {pristine_dir}")

    print("\nDone!")


if __name__ == "__main__":
    main()
